+            From = _from,
+            To = _to,
+            Take = 50
+        };
+    }
+
+    [Fact]
+    public void ToRecentRequest_MapsFilterFields()
+    {
+        var request = StructuredLogFilterMapper.ToRecentRequest(_filter, 100);
